 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # The source stamp is the largest connected non-background object; the
    # separate singleton objects are the locations where it should be copied.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x, grid[y][x]))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] != background):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            components.append(cells)

    source = max(components, key=len)
    sr0 = min(r for r, c, v in source)
    sr1 = max(r for r, c, v in source)
    sc0 = min(c for r, c, v in source)
    sc1 = max(c for r, c, v in source)
    stamp = {(r - sr0, c - sc0): v for r, c, v in source}
    anchor_r, anchor_c = (sr1 - sr0) // 2, (sc1 - sc0) // 2

    out = [row[:] for row in grid]
    for comp in components:
        if comp is source or len(comp) != 1:
            continue
        mr, mc, _ = comp[0]
        top, left = mr - anchor_r, mc - anchor_c
        for (dr, dc), value in stamp.items():
            rr, cc = top + dr, left + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = value
    return out
